/**
 * Public types for @grok/agent-sdk.
 *
 * The framework is filesystem-first: customers author an agent as files under
 * an `agent/` directory (markdown for prose, TypeScript for typed behavior),
 * and the framework discovers those files, compiles them into an
 * {@link AgentProject}, and serves the agent over channels using the Cursor
 * SDK as the execution harness.
 */
/**
 * Model used when the root agent omits `model` (local Cursor agents have no
 * harness-level default of their own).
 */
export const DEFAULT_MODEL = {
    id: "grok-4.5",
    params: [
        { id: "effort", value: "high" },
        { id: "fast", value: "true" },
    ],
};
function redactHttpUrlCredentials(url) {
    try {
        const parsed = new URL(url);
        if (parsed.username !== "" || parsed.password !== "") {
            parsed.username = "";
            parsed.password = "";
        }
        return parsed.toString();
    }
    catch {
        return url.replace(/^(https?:\/\/)[^@/]+@/i, "$1");
    }
}
export function toPublicCloudInfo(cloud) {
    const { envVars, repos, ...rest } = cloud;
    const hasEnvVars = envVars !== undefined && Object.keys(envVars).length > 0;
    return {
        ...rest,
        ...(repos !== undefined
            ? {
                repos: repos.map((repo) => ({
                    ...repo,
                    url: redactHttpUrlCredentials(repo.url),
                    ...(repo.prUrl !== undefined ? { prUrl: redactHttpUrlCredentials(repo.prUrl) } : {}),
                })),
            }
            : {}),
        ...(hasEnvVars ? { envVarsConfigured: true } : {}),
    };
}
/**
 * Hard ceiling for {@link AgentConcurrencyOptions.maxRunningTurns}.
 * Matches the eval harness ceiling: each running turn issues model
 * provider requests, so unbounded parallelism is never meaningful.
 */
export const MAX_RUNNING_TURNS_LIMIT = 200;
/**
 * Runtime probe: does this KV implement the CAS superset? Only for
 * stores of unknown provenance — e.g. a caller-supplied {@link HostKvApi}
 * object whose static type does not carry the CAS methods. A
 * `defineStorage` backend declares CAS through its `cas` group instead
 * and never needs probing.
 */
export function supportsKvCas(kv) {
    const candidate = kv;
    return (typeof candidate.getWithVersion === "function" &&
        typeof candidate.putIfAbsent === "function" &&
        typeof candidate.putIfVersion === "function" &&
        typeof candidate.listKeys === "function");
}
const TOOL_EFFECTS = ["read", "write", "idempotent"];
export function isToolEffect(value) {
    return value === "read" || value === "write" || value === "idempotent";
}
/**
 * Normalize authored {@link ConnectionConfig.effects} to a unique list.
 * Invalid values are left for discovery to reject — this only collapses
 * `"read"` / `["read"]` / duplicates.
 */
export function normalizeConnectionEffects(effects) {
    const list = typeof effects === "string" ? [effects] : [...effects];
    const unique = [];
    for (const effect of TOOL_EFFECTS) {
        if (list.includes(effect)) {
            unique.push(effect);
        }
    }
    return unique;
}
/**
 * Trim, drop blanks, and unique-preserve authored
 * {@link ConnectionConfig.tools} name lists. Invalid shapes are left
 * for discovery.
 */
export function normalizeConnectionTools(tools) {
    const unique = [];
    const seen = new Set();
    for (const raw of tools) {
        const name = raw.trim();
        if (name === "" || seen.has(name)) {
            continue;
        }
        seen.add(name);
        unique.push(name);
    }
    return unique;
}
/** True when `toolName` passes the connection's `tools` / `disallowedTools` filter. */
export function connectionAllowsTool(filter, toolName) {
    if (filter.tools !== undefined && !filter.tools.includes(toolName)) {
        return false;
    }
    return filter.disallowedTools === undefined || !filter.disallowedTools.includes(toolName);
}
/** True for the peer-agent transport variant (`{ agent: "<slug>" }`). */
export function isPeerConnectionTransport(transport) {
    return "agent" in transport;
}
/** True for the Cursor account transport variant (`{ cursorAccount: true }`). */
export function isCursorAccountTransport(transport) {
    return "cursorAccount" in transport && transport.cursorAccount;
}
/**
 * Normalize an authored Cursor account `servers` filter.
 *
 * `undefined`, `"*"`, and `["*"]` (after trim) all mean every connected
 * HTTP/SSE server on the account. Returns a concrete allowlist, or
 * `undefined` for all. Does not validate emptiness, blank entries, or a
 * mixed `"*"` + names list — discovery owns those diagnostics.
 */
export function normalizeCursorAccountServers(servers) {
    if (servers === undefined || servers === "*") {
        return undefined;
    }
    const trimmed = servers.map((server) => server.trim());
    if (trimmed.length === 1 && trimmed[0] === "*") {
        return undefined;
    }
    return [...servers];
}
/** True when an authored allowlist mixes `"*"` with other connector names. */
export function cursorAccountServersHasMixedWildcard(servers) {
    if (servers === undefined || servers === "*") {
        return false;
    }
    const trimmed = servers.map((server) => server.trim());
    return trimmed.includes("*") && trimmed.some((server) => server !== "*");
}
/**
 * True for an HTTP/SSE transport authorized with host PKCE OAuth
 * (`defineConnection({ url, oauth: true })`). The tokens live on the serve
 * host (`mcp-auth.json` / `MCP_OAUTH_*`), so only host-side MCP clients can
 * use them.
 */
export function isHostOauthConnectionTransport(transport) {
    return "url" in transport && transport.oauth === true;
}
/**
 * True for transports that stay symbolic at discovery time and are resolved
 * by the serve host once it is listening (peers and the Cursor account
 * bridge). Symbolic transports never reach the SDK or the host MCP registry
 * unresolved.
 */
export function isSymbolicConnectionTransport(transport) {
    return isPeerConnectionTransport(transport) || isCursorAccountTransport(transport);
}
/** True when the connection authors tools instead of a spawn/URL/peer. */
export function isInlineStdioConnection(connection) {
    return ("tools" in connection && connection.tools !== undefined && !Array.isArray(connection.tools));
}
export function isSecretRef(value) {
    return (typeof value === "object" &&
        value !== null &&
        typeof value.secretName === "string");
}
// ============================================================================
// Direct tool calls (deterministic invocation, no model turn)
// ============================================================================
/**
 * Channel id recorded on the synthetic session info handed to tools invoked
 * directly (outside any existing session).
 */
export const DIRECT_TOOL_CALL_CHANNEL_ID = "direct";
/** Reject a hosted startSession subject from {@link HttpChannelConfig.onAdmit}. */
export class HttpSessionAdmitError extends Error {
    constructor(message) {
        super(message);
        this.status = 400;
        this.name = "HttpSessionAdmitError";
    }
}
